-- Additive schema for enrollment, guardian access, staff duties, finance, CBC and LMS.
CREATE TABLE IF NOT EXISTS academic_years(year INTEGER PRIMARY KEY, active BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS academic_terms(id BIGSERIAL PRIMARY KEY, year INTEGER NOT NULL REFERENCES academic_years(year), term INTEGER NOT NULL CHECK(term BETWEEN 1 AND 3), starts_on DATE, ends_on DATE, UNIQUE(year,term));
CREATE TABLE IF NOT EXISTS enrollments(id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id), year INTEGER NOT NULL REFERENCES academic_years(year), grade TEXT NOT NULL, stream TEXT NOT NULL DEFAULT 'A', start_date DATE NOT NULL DEFAULT CURRENT_DATE, end_date DATE, UNIQUE(student_id,year));
CREATE TABLE IF NOT EXISTS guardian_accounts(guardian_id BIGINT NOT NULL REFERENCES guardians(id), user_id BIGINT NOT NULL REFERENCES users(id), PRIMARY KEY(guardian_id,user_id));
CREATE TABLE IF NOT EXISTS student_guardians(student_id BIGINT NOT NULL REFERENCES students(id), guardian_id BIGINT NOT NULL REFERENCES guardians(id), relationship TEXT NOT NULL DEFAULT 'guardian', PRIMARY KEY(student_id,guardian_id));
INSERT INTO student_guardians(student_id,guardian_id) SELECT id,guardian_id FROM students WHERE guardian_id IS NOT NULL ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS teacher_assignments(id BIGSERIAL PRIMARY KEY, staff_id BIGINT NOT NULL REFERENCES staff(id), year INTEGER NOT NULL, grade TEXT NOT NULL, stream TEXT NOT NULL DEFAULT 'A', subject TEXT NOT NULL, UNIQUE(staff_id,year,grade,stream,subject));
CREATE TABLE IF NOT EXISTS staff_duties(id BIGSERIAL PRIMARY KEY, staff_id BIGINT NOT NULL REFERENCES staff(id), title TEXT NOT NULL, starts_on DATE DEFAULT CURRENT_DATE, ends_on DATE);
CREATE TABLE IF NOT EXISTS fee_structures(id BIGSERIAL PRIMARY KEY, year INTEGER NOT NULL, term INTEGER NOT NULL CHECK(term BETWEEN 1 AND 3), grade TEXT NOT NULL, item TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), UNIQUE(year,term,grade,item));
CREATE TABLE IF NOT EXISTS fee_adjustments(id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id), amount NUMERIC(12,2) NOT NULL CHECK(amount<>0), reason TEXT NOT NULL, approved_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_allocations(id BIGSERIAL PRIMARY KEY, payment_id BIGINT NOT NULL REFERENCES payments(id), charge_id BIGINT NOT NULL REFERENCES fee_charges(id), amount NUMERIC(12,2) NOT NULL CHECK(amount>0), UNIQUE(payment_id,charge_id));
CREATE TABLE IF NOT EXISTS school_announcements(id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, audience TEXT NOT NULL DEFAULT 'all', created_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS learning_materials(id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', grade TEXT NOT NULL, subject TEXT NOT NULL, url TEXT NOT NULL, teacher_id BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS performance_levels(id BIGSERIAL PRIMARY KEY, scheme TEXT NOT NULL, code TEXT NOT NULL CHECK(code IN ('EE','ME','AE','BE')), minimum NUMERIC(5,2) NOT NULL, maximum NUMERIC(5,2) NOT NULL, CHECK(minimum<=maximum), UNIQUE(scheme,code));
CREATE TABLE IF NOT EXISTS competency_observations(id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id), subject TEXT NOT NULL, criterion TEXT NOT NULL, level TEXT NOT NULL CHECK(level IN ('EE','ME','AE','BE')), year INTEGER NOT NULL, term INTEGER NOT NULL CHECK(term BETWEEN 1 AND 3), recorded_by BIGINT NOT NULL REFERENCES users(id), UNIQUE(student_id,subject,criterion,year,term));
CREATE TABLE IF NOT EXISTS report_versions(id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id), year INTEGER NOT NULL, term INTEGER CHECK(term BETWEEN 1 AND 3), payload JSONB NOT NULL, approved_by BIGINT NOT NULL REFERENCES users(id), approved_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reporting_requirements(id BIGSERIAL PRIMARY KEY, year INTEGER NOT NULL, grade TEXT NOT NULL, item TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('document','material')), UNIQUE(year,grade,item));
CREATE TABLE IF NOT EXISTS reporting_requirement_checks(id BIGSERIAL PRIMARY KEY, application_id BIGINT NOT NULL REFERENCES applications(id), requirement_id BIGINT NOT NULL REFERENCES reporting_requirements(id), completed BOOLEAN NOT NULL DEFAULT false, verified_by BIGINT REFERENCES users(id), UNIQUE(application_id,requirement_id));
CREATE TABLE IF NOT EXISTS email_delivery_logs(id BIGSERIAL PRIMARY KEY, outbox_id BIGINT NOT NULL REFERENCES email_outbox(id), delivered_at TIMESTAMPTZ, error TEXT);
CREATE INDEX IF NOT EXISTS idx_enrollments_student ON enrollments(student_id,year);
CREATE INDEX IF NOT EXISTS idx_teacher_assignments ON teacher_assignments(staff_id,year,grade,subject);
CREATE INDEX IF NOT EXISTS idx_allocations_charge ON payment_allocations(charge_id);
CREATE INDEX IF NOT EXISTS idx_guardian_accounts_user ON guardian_accounts(user_id);
